import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h=len(g); w=len(g[0])
    # find line color: the background dominates; line = color forming full row/col
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    line=None; orient=None; pos=None
    for i,row in enumerate(g):
        if len(set(row))==1 and row[0]!=bg: line=row[0]; orient='h'; pos=i
    if line is None:
        for j in range(w):
            col={g[i][j] for i in range(h)}
            if len(col)==1 and next(iter(col))!=bg: line=next(iter(col)); orient='v'; pos=j
    # object cells
    cells=[(i,j) for i in range(h) for j in range(w) if g[i][j] not in (bg,line)]
    ci=[c[0] for c in cells]; cj=[c[1] for c in cells]
    r0,r1,c0,c1=min(ci),max(ci),min(cj),max(cj)
    obj=[[g[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    out=[[bg]*w for _ in range(h)]
    if orient=='h':
        dr = 1 if pos==0 or (pos<r0) else -1
        # move object so near edge adjacent to line
        if pos<r0: nr0=pos+1
        else: nr0=pos-1-(r1-r0)
        for i,row in enumerate(obj):
            for j,v in enumerate(row):
                if v!=bg: out[nr0+i][c0+j]=v
        # 8-line on far side of object
        fr = nr0+len(obj) if pos<r0 else nr0-1
        for j in range(w): out[fr][j]=8
    else:
        if pos<c0: nc0=pos+1
        else: nc0=pos-1-(c1-c0)
        for i in range(len(obj)):
            for j,v in enumerate(obj[i]):
                if v!=bg: out[r0+i][nc0+j]=v
        fc = nc0+len(obj[0]) if pos<c0 else nc0-1
        for i in range(h): out[i][fc]=8
    return out

